"""English rendering of server-returned text (stage 3). The English is taken verbatim from app/i18n_en.json (generated by tools/build_i18n.py from docs/i18n/zh_en_map.csv).

Approach: before the JSON is returned (_json in server.py) every string value is replaced with its English; this happens only when the request carries X-App-Lang: en (or ?lang=en),
Chinese mode never passes through here, and the response is byte-identical to before.
- Identical sentences (compared after collapsing whitespace to a single space) -> replaced directly.
- f-string sentences (e.g. the "N levels apart" template with {level_diff}) -> matched by pattern, then the captured values are put into the English template; if a captured value is itself Chinese (e.g. a level name) it is replaced once more.
- Strings made of several chained sentences (joined by the Chinese full stop or semicolon) -> split and replaced only if every sentence is in the table, English joined with a single space; if any sentence is missing the string stays as is (the audit tool tools/audit_api_strings.py finds these so the table can be filled in).
Strings not in the table are always returned unchanged: no guessing, no rewriting.
Protection (Security review): strings sent by the client can also be echoed back into the response, and the pattern regexes have several any-character groups, which become polynomial time for a malicious long string.
So: strings longer than MAX_TEMPLATE characters skip pattern matching (sentences the server generates are all short, the longest being 133 characters);
strings longer than MAX_TOTAL characters are not processed at all; before pattern matching, check that the fixed text in the pattern appears in order (if not, the regex need not run).
"""
from __future__ import annotations

import json
import re
from pathlib import Path

DATA = Path(__file__).with_name("i18n_en.json")
CJK = re.compile(r"[㐀-鿿＀-￯　-〿]")
PLACEHOLDER = re.compile(r"\{[^{}]*\}")
SENTENCE_END = re.compile(r"(?<=[。；！？])")
MAX_TEMPLATE = 400        # longer than this: no pattern matching
MAX_TOTAL = 3000          # longer than this: not processed at all (returned unchanged)


def norm(s: str) -> str:
    return " ".join(s.split())


class Localizer:
    def __init__(self, data: dict):
        self.exact = {norm(k): v for k, v in data.get("exact", {}).items()}
        self.templates = []
        for zh, en in data.get("templates", []):
            parts = PLACEHOLDER.split(zh)
            holders = PLACEHOLDER.findall(zh)
            if not holders:
                continue
            rx = "".join(re.escape(p) + (f"(?P<g{i}>.+?)" if i < len(holders) else "") for i, p in enumerate(parts))
            literals = [p for p in parts if p]
            self.templates.append((re.compile(rx + r"\Z", re.S), holders, en, literals))
        self.templates.sort(key=lambda t: -len(t[0].pattern))      # more specific (longer) patterns are tried first

    @staticmethod
    def _literals_in_order(key: str, literals: list) -> bool:
        pos = 0
        for lit in literals:
            i = key.find(lit, pos)
            if i < 0:
                return False
            pos = i + len(lit)
        return True

    def _fill(self, m: re.Match, holders: list, en: str) -> str:
        values = {}
        for i, h in enumerate(holders):
            values.setdefault(h, []).append(self.tr(m.group(f"g{i}")))
        used = {}

        def sub(mm: re.Match) -> str:
            h = mm.group(0)
            lst = values.get(h)
            if not lst:
                return h
            k = used.get(h, 0)
            used[h] = k + 1
            return lst[min(k, len(lst) - 1)]
        return PLACEHOLDER.sub(sub, en)

    def tr(self, s: str, _depth: int = 0) -> str:
        if not isinstance(s, str) or not CJK.search(s):
            return s
        if len(s) > MAX_TOTAL:
            return s
        key = norm(s)
        hit = self.exact.get(key)
        if hit is not None:
            return hit
        for rx, holders, en, literals in (self.templates if len(key) <= MAX_TEMPLATE else ()):
            if not self._literals_in_order(key, literals):
                continue
            m = rx.match(key)
            if m:
                return self._fill(m, holders, en)
        bare = key.rstrip("。；！？")                                # trailing punctuation does not affect matching (a sentence in the table may lack its end punctuation)
        if bare != key and bare:
            t = self.tr(bare, 1)
            if not CJK.search(t):
                return t
        if _depth == 0:                                           # several chained sentences: replaced only if every sentence is in the table
            pieces = [p for p in SENTENCE_END.split(key) if p.strip()]
            if len(pieces) > 1:
                out = []
                for p in pieces:
                    t = self.tr(p, 1)
                    if CJK.search(t):
                        return s
                    out.append(t)
                return " ".join(out)
        return s

    def localize(self, obj):
        if isinstance(obj, str):
            return self.tr(obj)
        if isinstance(obj, list):
            return [self.localize(x) for x in obj]
        if isinstance(obj, tuple):
            return [self.localize(x) for x in obj]
        if isinstance(obj, dict):
            return {k: self.localize(v) for k, v in obj.items()}
        return obj


_CACHE: dict = {}


def get() -> Localizer:
    if "l" not in _CACHE:
        data = json.loads(DATA.read_text(encoding="utf-8")) if DATA.exists() else {}
        _CACHE["l"] = Localizer(data)
    return _CACHE["l"]


def localize(obj):
    return get().localize(obj)
